import {getAction} from '@madou/catalog';
import {createGame,gameStats} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const metalGolemPhysicalScenarios=['metal-setup','metal-turn','metal-equal','metal-higher','metal-army','metal-mental','metal-mental-rear','metal-mental-destroy'] as const;
export type MetalGolemPhysicalScenario=typeof metalGolemPhysicalScenarios[number];
export function isMetalGolemPhysicalScenario(name:string):name is MetalGolemPhysicalScenario{return (metalGolemPhysicalScenarios as readonly string[]).includes(name);}
export function metalGolemPhysicalMode(name:MetalGolemPhysicalScenario){return{card:'a2-p22-r1c1',name:'メタルゴーレム',level:6,hp:5,attributes:['ゴ','鉄','地'],attackLevel:5,attackDamage:10,multi:name.endsWith('-equal')||name.endsWith('-higher'),sourceLevel:name.endsWith('-higher')?7:6,rear:name.endsWith('-rear'),attackAttributes:['近','戦','格'],grant:false,army:name.endsWith('-army'),mental:name.includes('-mental'),destroy:name.endsWith('-destroy'),initial:name.endsWith('-setup')||name.includes('-mental')||name.endsWith('-equal')||name.endsWith('-higher')};}
/** Every scenario starts in real initial placement; tests issue all placement and turn commands. */
export function makeMetalGolemPhysicalScenario(name:MetalGolemPhysicalScenario,players:{id:string;name:string}[],options:{dwarf?:boolean;level?:number;owner?:string;warrior?:number;spirit?:number}={}){
 const m=metalGolemPhysicalMode(name),s=createGame(players,entropy(),{startingSeat:0}),[a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,[options.dwarf||m.multi?'魔導王ガイナス':options.owner??'魔聖母ディア',options.dwarf||m.multi?'魔聖母ディア':m.mental?(m.destroy?'占星術師のアルセイル':'餓狼ヨーツルム'):'白魔術師シェリム','凍気のアイエル','侍大将のシン'][i]!);for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit=20+14-gameStats(s,p.id).spirit;}if(options.level!==undefined||m.multi)s.players[b]!.permanent!.warrior_level=20+(options.level??m.sourceLevel)-gameStats(s,b).warrior_level;
 if(options.spirit!==undefined)s.players[a]!.permanent!.spirit=s.players[a]!.permanent!.spirit!+options.spirit-gameStats(s,a).spirit;
 if(options.warrior!==undefined)s.players[a]!.permanent!.warrior_level=20+options.warrior-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,m.card),takeCard(s,a,'a2-p24-r1c3'),takeCard(s,a,'a2-p20-r2c3'),takeCard(s,a,m.army?'a2-p05-r2c2':m.mental?'a2-p18-r3c3':'a2-p23-r1c1'),takeCard(s,a,'a2-p07-r1c1'),takeCard(s,b,'a2-p24-r1c2'),takeCard(s,b,'a2-p24-r2c1'),takeCard(s,b,m.army?'a2-p07-r1c2':'a2-p21-r2c3'),takeCard(s,b,'a2-p11-r1c3'),...(m.mental?[takeCard(s,b,m.destroy?'a2-p13-r1c2':'a2-p16-r2c1')]:[]),takeCard(s,d,'a2-p02-r2c3')];for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')]; const cursors:Record<string,number>={};s.events=s.events.flatMap(event=>{if(event.type==='CHARACTER_ASSIGNED'&&event.actorId)return[{...event,characterId:s.players[event.actorId]!.characterId}];if(event.type!=='CARD_DRAWN'||!event.actorId)return[event];const index=cursors[event.actorId]??0;cursors[event.actorId]=index+1;const cardInstanceId=s.players[event.actorId]!.hand[index];return cardInstanceId?[{...event,cardInstanceId}]:[];});return s;
}
